	MOUNTRUN_DIFF_H = "Heroico",
	MOUNTRUN_DIFF_M = "Mítico",
	MOUNTRUN_Q_NHM = "Normal/Heroico/Mítico",
	MOUNTRUN_Q_KEEPERS0 = "0 guardianes",
	MOUNTRUN_Q_MPLUS = "Mítico o cofre de Mítico+",
