	MOUNTRUN_HEAD_DUNGEONS = "Calabozos: Normal se puede reiniciar, Heroico una vez al día, Mítico una vez a la semana",
	MOUNTRUN_HEAD_MYTHIC = "Noche 4 (opcional): el bloque en Mítico",
	MOUNTRUN_HOW_AMI = "Portal a Valdrakken, luego el portal al Sueño Esmeralda (hace falta una misión) y vuela hasta la banda. Mítico.",
	MOUNTRUN_HOW_ANT = "Portal a Azsuna, sube volando a Dalaran (Legion) y haz clic en el Faro templeluz para subir a bordo de El Vindicaar, sobre Argus. Lleva la nave a los Páramos Antorianos; la banda está en el centro. Los Canes manáfagos de Sargeras son el segundo jefe y sueltan el Can carbonizado antoriano en todas las dificultades, pero nadie sabe la probabilidad: un jugador lo intentó 332 veces. Buscador de bandas: Archimago Tiemporeja, ala Brecha de la Luz.",
	MOUNTRUN_HOW_ANT_ARGUS = "Se entra por el mismo camino. Argus es el último de 11 jefes y el Ur'zul encadenado solo cae en Mítico. El atajo al Trono ardiente (misiones Dark Passage y The Heart of Argus) te lleva a los dos últimos jefes.",
	MOUNTRUN_HOW_AOF = "Mismo camino a las Bóvedas de Atal'Utek; el calabozo está en el sur. Mítico (una vez al día esta temporada) o el cofre final de Mítico+. Hace falta un grupo.",
	MOUNTRUN_HOW_BOD = "Alianza: portal a Boralus, la entrada está en el puerto. Horda: portal a Zuldazar, la entrada está en Dazar'alor. Mítico, y nada de Ansia de sangre ni Heroísmo en la primera fase de Jaina.",
	MOUNTRUN_HOW_BOD_GMOD = "La misma banda que Jaina: Alianza en Puerto Boralus, Horda en Dazar'alor. Mekkatorque suelta el M.I.D.A.S.-G en Normal, Heroico y Mítico: tres intentos por semana. Buscador de bandas: Kiku en la posada de Boralus o Eppu en El Gran Sello de Dazar'alor, ala Victoria o muerte.",
	MOUNTRUN_HOW_BRF = "Alianza: portal a Escudo de Tormenta; Horda: portal a Lanza de Guerra. Vuela a Gorgrond, en el norte de Draenor. Mítico.",
	MOUNTRUN_HOW_COS = "Sala de portales: portal a las Cavernas del Tiempo (Tanaris), camina hasta el portal de La Matanza de Stratholme. Heroico, y termina a tiempo para el Draco bronce.",
	MOUNTRUN_HOW_DFC = "Portal a Dornogal, baja volando por el agujero de la ciudad a las Minas Resonantes; el calabozo está en el norte. Mítico una vez a la semana, o el cofre final de Mítico+. Hace falta un grupo.",
	MOUNTRUN_HOW_DOTI = "Portal a Valdrakken, vuela al sureste hasta el Conflujo Temporal, en Thaldraszus. Mítico, una vez a la semana; Deios es el último de ocho jefes. Las riendas se convierten en una montura de calabozo al azar que aún no tengas, incluida la mayoría de las monturas de esta lista.",
	MOUNTRUN_HOW_DS = "Portal a las Cavernas del Tiempo y luego el portal de Alma de Dragón. La Fámula de la Protectora solo cae en Heroico.",
	MOUNTRUN_HOW_FH = "Alianza: portal a Boralus, vuela al sur hasta la costa sureste del Canal de Tiragarde. Horda: portal a Zuldazar, barco al Canal de Tiragarde, vuela al sur. Mítico, una vez a la semana.",
	MOUNTRUN_HOW_HFC = "Alianza: portal a Escudo de Tormenta y luego a la Avanzada de León, en la Jungla Tanaan. Horda: portal a Lanza de Guerra y luego a Vol'mar. En ambos casos hace falta una misión. Mítico.",
	MOUNTRUN_HOW_ICC = "Portal a Dalaran (Rasganorte), vuela a la Ciudadela de la Corona de Hielo, en el sur de Corona de Hielo. Solo 25 Heroico suelta Invencible.",
	MOUNTRUN_HOW_LOU = "Portal a Dornogal, luego la plataforma de teletransporte brillante a Minahonda; la puerta de la banda está en el centro de la ciudad. Prototipo A.S.M.R. en todas las dificultades, El Gran G solo en Mítico. Hace falta un grupo.",
	MOUNTRUN_HOW_MFO = "Portal a Dornogal, luego la Falla espacial a Tazavesh, en K'aresh (hace falta una misión); vuela al norte hasta la Forja de Maná. Solo Mítico. Hace falta un grupo.",
	MOUNTRUN_HOW_MOQD = "Sala de portales: portal a Lunargenta, vuela al norte hasta la Isla de Quel'Danas; la puerta de la banda está en el extremo sur. Solo Mítico, banda actual: hace falta un grupo completo.",
	MOUNTRUN_HOW_MT = "Portal a Shattrath y luego el portal a la Isla de Quel'Danas, en el centro de Shattrath: esa es la isla ANTIGUA, con el antiguo Bancal del Magister. No el nuevo calabozo de Midnight en Lunargenta. Heroico.",
	MOUNTRUN_HOW_MTN = "Portal a Lunargenta, vuela al norte hasta la Isla de Quel'Danas; el nuevo Bancal del Magister está en el noreste (no el antiguo por Shattrath). Mítico, una vez al día. Hace falta un grupo.",
	MOUNTRUN_HOW_NH = "Portal a Azsuna, vuela a la Ciudad de Suramar. Mítico.",
	MOUNTRUN_HOW_NP = "Portal a Dornogal, luego el túnel del lado este a Azj-Kahet (hace falta una misión); el palacio está en el extremo sur. Cuchilla del cielo sureki en todas las dificultades, Cuchilla del cielo ascendiente solo en Mítico. Hace falta un grupo: las bandas de The War Within aún no son contenido antiguo.",
	MOUNTRUN_HOW_NYA = "Santuario de la Tierra: portal a Uldum. La entrada flota sobre la Presa Vir'naal, pero solo en la línea temporal de N'Zoth: habla con Zidormi. Algunas semanas está en el Valle de la Flor Eterna. Cada personaje necesita antes la campaña del Imperio Negro hasta la misión de Magni A Titanic Problem. Solo Mítico.",
	MOUNTRUN_HOW_RTK = "La misma torre que Karazhan, por la puerta lateral. Mítico. Nightbane solo aparece si recoges sus cristales a tiempo.",
	MOUNTRUN_HOW_SC = "Santuario de la Tierra: portal a Infralar; El Núcleo Pétreo está justo al lado del Templo de la Tierra, donde llegas. Normal: reinicia y vuelve a hacerlo (10 instancias por hora). Heroico: una vez al día.",
	MOUNTRUN_HOW_SETHEKK = "Portal a Shattrath, vuela hacia el sur hasta Auchindoun, en el Bosque de Terokkar; las Salas Sethekk son una de las puertas hundidas. Heroico.",
	MOUNTRUN_HOW_SFO = "Portal a Oribos, el portal a Zereth Mortis (hace falta una misión) y vuela al este hasta el Sepulcro. Mítico. Cuando el Carcelero tome el control de ti, escóndete detrás de un pilar.",
	MOUNTRUN_HOW_SOD = "Sala de portales: portal a Oribos. En el piso de arriba, salta a la columna de luz del centro para llegar a Las Fauces; el Sagrario está en el noreste. Solo Mítico. La misión de atajo Damned If You Don't te ahorra casi toda la banda.",
	MOUNTRUN_HOW_SOO = "Portal a El Bosque de Jade, vuela al Valle de la Flor Eterna (parte este). Zidormi pone el Valle en la época correcta. Mítico.",
	MOUNTRUN_HOW_STRAT = "Osahendido es el último jefe de Stratholme - Entrada de Servicio, en el lado este de Stratholme, no de Stratholme - Entrada Principal. Horda: portal de la torre de zepelines de Orgrimmar a los Claros de Tirisfal, vuela al este. Alianza: vuela al norte desde Forjaz. Normal no tiene bloqueo: sal, reinicia y vuelve a entrar (como mucho 10 instancias por hora).",
	MOUNTRUN_HOW_TOS = "Sala de portales de Ventormenta u Orgrimmar: portal a Azsuna, vuela al sureste hasta la Costa Quebrada; la Tumba está en la costa noreste. El gusano cae en todas las dificultades, y Sassz'ine está en la primera parte de la banda, así que no uses el atajo de la banda. Buscador de bandas: Archimago Tiemporeja, fuera de El Bastión Violeta en Dalaran (Legion), ala Las puertas del infierno.",
	MOUNTRUN_HOW_ULDUAR = "Portal a Dalaran (Rasganorte), vuela a Ulduar, en el extremo norte de Las Cumbres Tormentosas. Lucha contra Yogg-Saron sin la ayuda de ningún guardián: no hables con ellos.",
	MOUNTRUN_HOW_UP = "Portal a Dalaran (Rasganorte), vuela a la Fortaleza de Utgarde, en el Fiordo Aquilonal; la puerta del Pináculo está arriba del todo. Heroico.",
	MOUNTRUN_HOW_UR = "Horda: portal a Zuldazar, vuela al norte hasta Nazmir. Alianza: portal a Boralus, barco a Nazmir. La entrada está en el centro de Nazmir. Mítico, una vez a la semana.",
	MOUNTRUN_HOW_VA = "Portal a Lunargenta, luego el portal a la Isla Serpenteante (se abre tras la misión de Astalor Presa: Una amenaza serpenteante). Baja bajo tierra a las Bóvedas de Atal'Utek; la banda está en el norte. Solo Mítico, banda actual: hace falta un grupo completo.",
	MOUNTRUN_HOW_VP = "Santuario de la Tierra: portal a Uldum, vuela a la esquina del extremo sureste. Normal: reinicia y vuelve a hacerlo (10 instancias por hora). Heroico: una vez al día.",
	MOUNTRUN_HOW_WRS = "Portal a Lunargenta, vuela al suroeste por el Bosque Canción Eterna hasta la Aguja Brisaveloz. Mítico, una vez al día. Hace falta un grupo.",
	MOUNTRUN_HOW_ZG = "Noreste del Norte de la Vega de Tuercespina. Alianza: vuela al sur desde Ventormenta pasando por el Bosque del Ocaso. Horda: zepelín de Orgrimmar a Grom'gol, vuela al noreste. Solo Heroico, una vez al día: Mandokir suelta el raptor, Kilnara la pantera.",
	MOUNTRUN_R_ANT = "Antorus, el Trono ardiente",
	MOUNTRUN_R_ANT_ARGUS = "Antorus, el Trono ardiente (Argus)",
	MOUNTRUN_R_AOF = "Altar de Colmillos",
	MOUNTRUN_R_BOD = "La Batalla de Dazar'alor",
	MOUNTRUN_R_BOD_GMOD = "La Batalla de Dazar'alor (Mekkatorque)",
	MOUNTRUN_R_BRF = "Fundición de Roca Negra",
	MOUNTRUN_R_DFC = "Grieta Llama Oscura",
	MOUNTRUN_R_DOTI = "El Alba del Infinito",
	MOUNTRUN_R_FH = "Puerto Libre",
	MOUNTRUN_R_MOQD = "Marcha sobre Quel'Danas",
	MOUNTRUN_R_NH = "La Fortaleza Nocturna",
	MOUNTRUN_R_NP = "Palacio Nerub-ar",
	MOUNTRUN_R_NYA = "Ny'alotha, la Ciudad Despierta",
	MOUNTRUN_R_STRAT = "Stratholme - Entrada de Servicio",
	MOUNTRUN_R_UR = "Bardoma",
	MOUNTRUN_R_VA = "El Abismo Venenoso",
	MOUNTRUN_STEP_BEACON = "Usa el Faro templeluz para ir a %s; luego lleva la nave a los Páramos Antorianos desde su consola.",
	MOUNTRUN_STEP_RING = "Súbete al Anillo de Transferencia para subir a %s.",
	MOUNTRUN_TAB_DUNGEONS = "Calabozos",
	MPLUS_AFFIX_LINDORMI ="Guía de Lindormi — marca y debilita a ciertos enemigos, y elimina la penalización por muerte. Una ayuda mientras aprendes los calabozos.",
	MPLUS_AFFIX_UNMEASURED = "La Temporada 2 cambió los afijos de las llaves y Midnight Helper todavía no ha medido los nuevos. La lista que había aquí era la de la Temporada 1, y mostrarla bajo un título de Temporada 2 sería peor que no mostrar nada. El grupo de calabozos de abajo sí está al día. Tu propia llave enseña los afijos antes de que podamos medirlos: /mh report y entran.",
	MPLUS_BEGINNER_INTRO = "Una \"key\" (keystone) es solo un calabozo en un ajuste más difícil con un reloj. No tienes que empezar ahí. No hay prisa y no pasa nada por ir despacio — casi todo el mundo aprende primero un calabozo y sube más adelante.",
	MPLUS_BEGINNER_START = "Empieza aquí: haz el calabozo primero en Follower o Normal. Sin reloj, morir no estropea nada, y vas a tu propio ritmo. Cuando te resulte fácil, prueba Heroic, luego Mythic 0 (todavía sin reloj), y solo después una +2 key.",
	MPLUS_CMD_FIRST_KEY = "¿Nunca has hecho una key? Escribe /mh codex y abre Calabozos y M+: 'Mythic+, desde tu primera key' te lo explica paso a paso.",
	MPLUS_CMD_GEAR_HINT = "Equipo: pasa el ratón por una piedra angular para ver los niveles de objeto exactos que da. El cofre del final va de Campeón a Héroe; solo la Gran bóveda da Mito, desde +10.",
	MPLUS_CMD_HEADER = "Mítico+ esta semana",
	MPLUS_CMD_NONE = "Aún no cuenta ninguna carrera de Mítico+ esta semana.",
	MPLUS_CMD_PERDUNGEON = "Por calabozo (tu mejor de la temporada):",
	MPLUS_CMD_RATING_NOTE = "Una llave completada a tiempo por encima de tu mejor marca en un calabozo sube tu puntuación — la descripción de la piedra angular muestra la proyección exacta.",
	MPLUS_GAIN_NEXT_FMT = "Siguiente ranura de la bóveda: %d carrera(s) más.",
	MPLUS_GLOSS_AFFIX = "Affix — una regla extra que hace el calabozo más difícil. Aparecen nuevas en ciertos niveles de key.",
	MPLUS_GLOSS_KEY = "Key / Keystone — un calabozo en un ajuste más difícil con un reloj. Un número más alto significa más difícil.",
	MPLUS_GLOSS_VAULT = "Ranura de bóveda — una opción de recompensa en la Gran bóveda. Haz actividades durante la semana para desbloquear más ranuras.",
	MPLUS_INTRO = "Cómo funcionan las llaves esta temporada: los afijos, el pool de 8 calabozos y los lanzamientos que debes interrumpir. Escrito a partir del resumen de Wowhead y method.gg — confirmar en el juego.",
	MPLUS_KICK_HEADER = "Lanzamientos de interrupción obligatoria (por calabozo)",
	MPLUS_KICK_NEXUSPOINT = "Punto del Nexo Xenas: kickea {SPELL:1250553} en Chief Corewright Kasreth, y en el trash {SPELL:1258681} (Grand Nullifier) > {SPELL:1271094} (Nexus Adept) > {SPELL:1263892} (Lightwrought). En el {SPELL:1257595} de Lothraxion, interrumpe la sombra SIN cuernos — kickear la equivocada perjudica al grupo.",
	MPLUS_KICK_NOTE = "Los grandes a vigilar — nombres confirmados de las guías, confirmar en el juego. Se añaden más calabozos a medida que verificamos sus listas de lanzamientos.",
	MPLUS_POOL_HEADER = "Los 8 calabozos de esta temporada",
	MPLUS_POOL_NOTE = "Normal y Seguidor usan todos los calabozos de lanzamiento; Heroico, Mítico 0 y Mythic+ usan este pool. Abre cualquier calabozo en la pestaña Dungeon Coach para los pasos por jefe.",
	MPLUS_SYSTEM = "• Las llaves empiezan en +2 (no en +4 como antes).|n• Resilient Keystones: cronometra los 8 calabozos en +12 y tu llave nunca baja de +12 en una degradación (y escala hacia arriba desde ahí).|n• Las Dungeon Waystones son puntos de control a mitad de run — los jugadores muertos reaparecen en el último que hayas desbloqueado.|n• El botín y los emblemas escalan con el nivel de llave: emblemas de nivel Campeón en llaves bajas hasta emblemas de nivel Mito en +10 y superiores, más una ranura de calabozo de la Gran bóveda por completar ocho.",
	MPLUS_WEEK_BODY = "• Abre el buscador de grupos y elige un calabozo en Follower o Normal.|n• No hay reloj y no puedes \"fallar\" — tómate todo el tiempo que necesites.|n• Puedes salir en cualquier momento; no se pierde nada.|n• Morir es normal y aquí no cuesta nada — solo vuelve andando y sigue.|n• ¿Quieres los pasos de cada jefe? Abre la pestaña Dungeon Coach.",
	MPLUS_WEEK_BONUS_FMT = "Bonus esta semana: %s es el calabozo de la semana — reputación extra cuando la haces.",
	NAV_PANEL_KEYSTONE = "Panel de la Gran bóveda",
	NAV_TOOL_BOSSWIN = "Ventana de jefes de calabozo",
	OMNIUM_OPEN_GARRISON = "Tu botón del minimapa está mostrando una página de ciudadela o de pacto, no la de Midnight. El folio se abre desde ese botón, así que no se puede llegar a él hasta que el botón vuelva a cambiar.",
	OMNIUM_WK_OBJ_4 = "Esta semana: derrota a un jefe final de calabozo/abismo o de ala LFR (saquéalo).",
	PLAYCARD_102_HERO1 = "Elegido de Elune: solo puedes entrar en Eclipse lunar. Rellena con {SPELL:194153}. Pulsa {SPELL:202770} dentro de Eclipse, en cuanto esté listo.",
	PLAYCARD_102_HERO2 = "Protector de la arboleda: {SPELL:205636} justo antes de {SPELL:1233346} o de {SPELL:194223}. También pone {SPELL:8921} en el objetivo.",
	PLAYCARD_103_HERO1 = "Druida de la zarpa: Devastar se ilumina en lugar de {SPELL:22568}. Púlsalo con 5 puntos de combo y 50 de Energía.",
	PLAYCARD_103_HERO2 = "Acechafieras: ningún botón nuevo. Sigue los pasos de arriba.",
	PLAYCARD_104_HERO1 = "Druida de la zarpa: Devastar a veces se ilumina en lugar de {SPELL:6807}: un golpe más grande que también da a los enemigos que tienes delante.",
	PLAYCARD_104_HERO2 = "Elegido de Elune: {SPELL:204066} siempre que esté listo. Rellena con {SPELL:8921} en vez de {SPELL:213764}.",
	PLAYCARD_105_HERO1 = "Acechafieras (el mejor esta temporada): ningún botón nuevo. {SPELL:18562} deja una flor: ese objetivo recibe más sanación.",
	PLAYCARD_105_HERO2 = "Protector de la arboleda: ningún botón nuevo. Cada arbolito ayudante hace tus sanaciones más fuertes, y a veces {SPELL:18562} también llama a una dríade que lanza un pequeño {SPELL:740}.",
	PLAYCARD_105_S1 = "Mantén {SPELL:33763} siempre activo: en el tanque, o en ti mismo en una banda. Con el talento Pasos de vida, tu {SPELL:145205} lo sigue; sin él, ponlo debajo del grupo.",
	PLAYCARD_1467_HERO1 = "Dracomandante (el mejor esta temporada): {SPELL:357210} siempre que esté listo, antes de {SPELL:375087}. Para el vuelo en cuanto llegues a los enemigos.",
	PLAYCARD_1467_HERO2 = "Formallamas: mantén la quemadura de {SPELL:357208} en el objetivo; {SPELL:356995} la hace explotar. Nada de {SPELL:370553} en {SPELL:357208}.",
	PLAYCARD_1467_S3 = "Gasta Esencia en {SPELL:356995}. ¿Se ilumina Ráfaga esencial? Úsala: es gratis.",
	PLAYCARD_1468_HERO1 = "Formallamas (el mejor esta temporada): {SPELL:355936} tiene 2 cargas. Usa una siempre que esté lista; la segunda, cuando llegue mucho daño.",
	PLAYCARD_1468_HERO2 = "Celatempus: {SPELL:370553} siempre que esté listo, y {SPELL:360995} a menudo: cada uno te hace más rápido.",
	PLAYCARD_1468_S3 = "Gasta Esencia en {SPELL:364343}. ¿Se ilumina Ráfaga esencial? {SPELL:355913}: es gratis.",
	PLAYCARD_1473_HERO1 = "Celatempus (el mejor esta temporada): {SPELL:370553} también te hace más rápido. Púlsalo junto con {SPELL:403631}.",
	PLAYCARD_1473_HERO2 = "Dracomandante: {SPELL:395160} pega más fuerte. Los botones son los mismos.",
	PLAYCARD_1480_HERO2 = "Aniquilador (el mejor esta temporada): con 3 acumulaciones de Lluvia del Vacío, {SPELL:1226019} enseguida. Como demonio, {SPELL:1221150} siempre que se ilumine.",
	PLAYCARD_251_HERO2 = "Jinete del apocalipsis: ningún botón extra. Los jinetes vienen solos; sigue los pasos de arriba.",
	PLAYCARD_252_AOE = "Pon {SPELL:43265} debajo del grupo de enemigos (con el talento Ciclo de la muerte). 3 o más enemigos: {SPELL:207317} en vez de {SPELL:47541}.",
	PLAYCARD_252_HERO1 = "Jinete del apocalipsis: ningún botón extra. Los jinetes vienen solos; sigue los pasos de arriba.",
	PLAYCARD_252_IDEA = "Genera necrófagos menores con {SPELL:85948}, úsalos con {SPELL:55090} y gasta Poder rúnico en {SPELL:47541}.",
	PLAYCARD_252_S4 = "¿Sin necrófagos menores? {SPELL:85948}. ¿Tienes alguno? {SPELL:55090}.",
	PLAYCARD_252_TERMS = "Un necrófago menor es un pequeño ayudante que lucha por ti un rato. {SPELL:85948} te da cargas para ellos, y cada {SPELL:55090} gasta una carga para llamar a un necrófago; el número en el botón de {SPELL:55090} muestra cuántas quedan.",
	PLAYCARD_252_W4 = "{SPELL:85948} carga tu arma para que tus siguientes {SPELL:55090} llamen cada uno a un necrófago menor que lucha por ti. {SPELL:55090} también hace estallar tus enfermedades para hacer daño extra.",
	PLAYCARD_255_HERO1 = "Centinela (el mejor esta temporada): {SPELL:1250646} se convierte una vez en Chakram de luz lunar; lánzalo antes de que acabe Derribar. ¿Se ilumina Marca de centinela en el objetivo? {SPELL:259495} de inmediato.",
	PLAYCARD_255_HERO2 = "Líder de manada: cuando se ilumine Aullido de líder de la manada, {SPELL:259489} llama a una bestia. Durante {SPELL:1250646}, apunta la línea de la Estampida.",
	PLAYCARD_256_HERO1 = "Tejedor del Vacío (el mejor en bandas): {SPELL:8092} abre una grieta que sigue al enemigo. Mientras esté abierta, {SPELL:585} se convierte en {SPELL:450215}: sigue lanzándolo. Puedes moverte; incluso eres más rápido mientras la grieta está abierta.",
	PLAYCARD_256_HERO2 = "Oráculo (el mejor en calabozos): {SPELL:47540} gana una segunda carga. Lanza {SPELL:17} justo después de cada {SPELL:47540}.",
	PLAYCARD_257_AOE = "Grupo herido: {SPELL:596} y {SPELL:34861}, si los tienes. Todos con poca salud: {SPELL:64843}, o {SPELL:200183} para más Palabras Sagradas.",
	PLAYCARD_257_EASY = "1. {SPELL:33076} cada vez que esté listo, incluso con todos a tope de salud: los cura cuando les golpean.\n2. ¿Alguien con poca salud? {SPELL:2050} (una Palabra Sagrada: vuelve rápido, así que no la guardes). ¿No está lista? {SPELL:2061}: hace que {SPELL:2050} vuelva antes.\n3. ¿Nadie necesita sanación? {SPELL:88625}, {SPELL:14914} y {SPELL:585} al enemigo.",
	PLAYCARD_257_IDEA = "Cura con tus Palabras Sagradas. {SPELL:2061}, {SPELL:596} y {SPELL:585} hacen que vuelvan antes.",
	PLAYCARD_257_TERMS = "Las Palabras Sagradas son tres hechizos fuertes con un tiempo de reutilización largo: {SPELL:2050} para un aliado, {SPELL:34861} para un grupo, {SPELL:88625} para un enemigo. Cada una vuelve antes cuando lanzas su compañero: {SPELL:2061}, {SPELL:596} y {SPELL:585}. Un talento puede sustituir {SPELL:34861}; entonces {SPELL:596} hace que {SPELL:2050} vuelva antes.",
	PLAYCARD_257_WAOE = "{SPELL:596} cura a cinco aliados a la vez y hace que {SPELL:34861} vuelva antes. {SPELL:64843} cura a todos los que están cerca de ti y hace más fuerte toda la sanación sobre ellos; {SPELL:200183} deja tus Palabras Sagradas listas otra vez al momento.",
	PLAYCARD_258_HERO2 = "Tejedor del Vacío: {SPELL:263165} abre una grieta. Mientras esté abierta, {SPELL:8092} se convierte en {SPELL:450983}: púlsalo siempre que esté listo.",
	PLAYCARD_259_HERO1 = "Mortacechador: {SPELL:703} pone tu marca en el objetivo. Cuando se ilumine La noche más oscura, {SPELL:32645} con 7 puntos de combo.",
	PLAYCARD_259_HERO2 = "Sinoatado: nada extra que pulsar. Tus remates lanzan monedas por sí solos; usa los botones normales.",
	PLAYCARD_260_HERO1 = "Tramposo (el mejor esta temporada): tras 4 golpes de Hoja invisible, {SPELL:2098} se convierte en Golpe de gracia. Púlsalo enseguida: cuenta como 5 puntos de combo extra, así que tus cooldowns también vuelven antes.",
	PLAYCARD_260_HERO2 = "Sinoatado: nada extra que pulsar, las monedas se lanzan solas. Usa {SPELL:2098} ya con 5 puntos de combo.",
	PLAYCARD_260_W2 = "{SPELL:1214909} da una bonificación al azar en 4 niveles, y cada nivel también tiene todo lo de debajo. Desde el nivel 2 (Doble problema), {SPELL:193315} da un punto de combo extra. Una tirada nueva borra la anterior, así que tira solo cuando no tengas ninguna o solo el nivel 1 (Único).",
	PLAYCARD_261_HERO1 = "Mortacechador (el mejor esta temporada): abre con {SPELL:185438} para poner tu marca, y entra en {SPELL:185313} con pocos puntos de combo. Cuando se ilumine La noche más oscura, tu siguiente {SPELL:196819} con 6 o más puntos va primero.",
	PLAYCARD_261_HERO2 = "Tramposo: entra en {SPELL:185313} con los puntos de combo llenos. Cuando se ilumine Golpe de gracia, pulsa {SPELL:196819} para usarlo.",
	PLAYCARD_261_MISTAKE = "Usar {SPELL:185313} cuando {SPELL:280719} no está listo. Excepciones: la segunda durante {SPELL:121471}, y como Mortacechador cuando La noche más oscura está iluminada.",
	PLAYCARD_262_HERO2 = "Portador de tormentas: sin {SPELL:443454}. Lanza {SPELL:454009} cada vez que se ilumine, en vez de {SPELL:188196}.",
	PLAYCARD_263_HERO1 = "Portador de tormentas (el mejor esta temporada): se ilumina {SPELL:454009}: lánzalo con 10 acumulaciones en vez de {SPELL:188196}. {SPELL:114051} es tu ráfaga de 2 minutos.",
	PLAYCARD_263_HERO2 = "Totémico: cada minuto {SPELL:444995}, luego {SPELL:197214}, luego {SPELL:384352}. ¿Se ilumina Mano ardiente? {SPELL:60103} primero.",
	PLAYCARD_263_W2 = "{SPELL:470057} siempre es crítico, pone {SPELL:470411} en tu objetivo y en algunos enemigos cercanos, y te da {SPELL:187880}; con el conjunto de esta temporada también provoca Nova de fuego. {SPELL:187874} golpea todo lo que tienes delante, y durante un rato después, {SPELL:17364} y {SPELL:60103} también electrocutan a esos enemigos.",
	PLAYCARD_264_HERO1 = "Totémico (el mejor esta temporada): {SPELL:444995} sustituye a {SPELL:73920}. Mantenlo puesto donde esté el grupo. {SPELL:378081} siempre que esté listo: hace que se ilumine Tótem corretormenta.",
	PLAYCARD_264_HERO2 = "Clarividente: {SPELL:443454} siempre que esté listo: viene un ancestro a curar contigo y se ilumina Tótem corretormenta. Tu gran cooldown es {SPELL:114052}.",
	PLAYCARD_264_S1 = "{SPELL:5394} siempre que esté listo. Con los dos talentos que le dan una segunda carga, nunca dejes las dos cargas llenas. Con el talento {SPELL:1267016}, {SPELL:61295} puede convertirlo en Tótem corretormenta, una de tus mayores curaciones: dura un minuto, así que úsalo dentro de ese tiempo.",
	PLAYCARD_265_AOE = "{SPELL:980} en todos los enemigos que puedas (hasta unos 10). 3 o más juntos: {SPELL:27243} para poner {SPELL:172} en todos; gasta Fragmentos de alma en él a partir de 6 enemigos (a partir de 3 con el talento Sembrar las semillas); si no, sigue con {SPELL:1259790}.",
	PLAYCARD_265_HERO2 = "Clamainfierno: {SPELL:172} se convierte en {SPELL:445468}. Guarda unos cuantos Fragmentos de alma, pulsa {SPELL:442726} y luego gástalos.",
	PLAYCARD_266_W1 = "El Tirano de {SPELL:265187} pega más fuerte por cada diablillo salvaje y Acechador nefasto que haya fuera, contados todo el tiempo que lucha. Así que cada {SPELL:105174} justo después de él añade diablillos que lo hacen más fuerte, y con {SPELL:1276163} también llama a demonios extra.",
	PLAYCARD_266_W2 = "{SPELL:104316} llama a dos Acechadores nefastos que pegan fuerte. Cuando se van, siempre te dan un {SPELL:267102}, y mientras están fuera hacen más fuerte tu {SPELL:265187}.",
	PLAYCARD_267_AOE = "2 enemigos: {SPELL:80240} en el segundo (si lo tienes), para que tus hechizos den a ambos. 3 o más juntos (4 o más como Clamainfierno): {SPELL:5740} en vez de {SPELL:116858}.",
	PLAYCARD_267_HERO1 = "Clamainfierno (el mejor en bandas): {SPELL:348} se convierte en {SPELL:445468}. {SPELL:442726} siempre que esté listo; gasta Fragmentos de alma mientras dure.",
	PLAYCARD_267_HERO2 = "Diabolista (el mejor en calabozos): cuando un demonio esté listo para salir, lanza {SPELL:116858}, incluso contra grupos: eso llama al demonio. Tras un señor del foso se convierte en Ruina: púlsalo.",
	PLAYCARD_268_HERO1 = "Shadopan (el mejor en calabozos): durante {SPELL:132578}, sigue pulsando {SPELL:115181} y {SPELL:121253}.",
	PLAYCARD_270_AOE = "Todo el grupo con poca salud: {SPELL:115310} (o {SPELL:388615}), o {SPELL:322118} en bandas y {SPELL:325197} en calabozos. No todo a la vez.",
	PLAYCARD_577_HERO1 = "Cicatrizvil (el mejor esta temporada): en {SPELL:191427}, usa Mirada abisal y Fuego consumidor cuando se iluminen.",
	PLAYCARD_577_HERO2 = "Atracador aldrachi: {SPELL:442294} siempre que esté listo, luego {SPELL:162794} y {SPELL:188499}: después pegan más fuerte.",
