	PLAYCARD_581_HERO2 = "Atracador aldrachi: {SPELL:442294} cuando esté listo, luego {SPELL:263642}, luego {SPELL:228477}: los dos pegan más fuerte.",
	PLAYCARD_62_AOE = "{SPELL:153626} siempre que esté listo. Con menos de 4 Cargas Arcanas, Pulso arcano (si lo tienes) en vez de {SPELL:30451}.",
	PLAYCARD_62_HERO1 = "Furia del Sol (el mejor esta temporada): cuando termina {SPELL:365350}, obtienes Alma arcana. Pulsa {SPELL:44425} una y otra vez mientras dure.",
	PLAYCARD_62_HERO2 = "Lanzahechizos: {SPELL:44425} con 20 de Andanada arcana en vez de 25.",
	PLAYCARD_62_IDEA = "Acumulas 4 Cargas Arcanas y acumulaciones de Andanada arcana, y luego lo sueltas todo de golpe con {SPELL:44425}.",
	PLAYCARD_62_S4 = "4 Cargas Arcanas y Andanada arcana llena (25 acumulaciones): {SPELL:44425}.",
	PLAYCARD_63_AOE = "4 o más enemigos: {SPELL:2120} en vez de {SPELL:11366} cuando se ilumine ¡Una buena racha!",
	PLAYCARD_63_HERO1 = "Furia del Sol (el mejor esta temporada): cuando termina {SPELL:190319}, {SPELL:11366} es instantáneo y siempre crítico durante un rato. Sigue pulsándolo.",
	PLAYCARD_63_IDEA = "Consigue dos críticos seguidos para encender ¡Una buena racha! y luego lanza {SPELL:11366} al instante.",
	PLAYCARD_63_S2 = "¿Se ilumina Calentamiento? {SPELL:108853} lo convierte en ¡Una buena racha! Funciona incluso durante otro lanzamiento.",
	PLAYCARD_63_S3 = "Con ¡Una buena racha! encendida: {SPELL:11366}. Mejor justo cuando termina {SPELL:133}, para que ambos impacten a la vez.",
	PLAYCARD_63_S4 = "¿Se ilumina Piroestruendo? Lanza {SPELL:11366} con tiempo de lanzamiento: pega mucho más fuerte.",
	PLAYCARD_64_AOE = "3 o más enemigos: apunta {SPELL:84714} al grupo de enemigos y luego {SPELL:190356} (con el talento Lluvia helada se ilumina y es instantáneo).",
	PLAYCARD_64_HERO1 = "Lanzahechizos (el mejor contra un solo objetivo): {SPELL:30455} a partir de 6 acumulaciones de Congelamiento en el enemigo.",
	PLAYCARD_64_HERO2 = "Pirofrío (algo mejor en calabozos): {SPELL:431044} sustituye a {SPELL:116}. {SPELL:153595} cuando aparezca. {SPELL:30455} a partir de 12 acumulaciones de Congelamiento. Guarda una sola carga de Dedos de Escarcha: úsala solo cuando {SPELL:1247729} esté activo, o en cuanto tengas 2.",
	PLAYCARD_64_IDEA = "Acumula Congelamiento en el enemigo con {SPELL:116} y luego hazlo añicos con {SPELL:30455}.",
	PLAYCARD_64_MISTAKE = "Pulsar {SPELL:205021} primero porque es tu gran botón. Gasta antes el Congelamiento con {SPELL:30455}, luego el rayo.",
	PLAYCARD_64_S3 = "¿Se ilumina Dedos de Escarcha, o hay mucho Congelamiento en el enemigo? {SPELL:30455}.",
	PLAYCARD_64_TERMS = "El Congelamiento es una marca de hielo en tu enemigo. {SPELL:116} añade 1, {SPELL:44614} añade 3, {SPELL:205021} añade 8, y un enemigo aguanta como mucho 20. {SPELL:30455} rompe 4 a la vez (más con talentos) para hacer daño extra: eso se llama {SPELL:1246769}.",
	PLAYCARD_64_W2 = "{SPELL:190447} te devuelve {SPELL:44614} al momento y hace que golpee más fuerte. {SPELL:44614} pone 3 acumulaciones de Congelamiento de una vez.",
	PLAYCARD_64_W3 = "{SPELL:30455} rompe 4 acumulaciones de Congelamiento a la vez (más con talentos) para hacer mucho daño. Con {SPELL:112965} golpea igual de fuerte, y el Congelamiento se queda.",
	PLAYCARD_64_W4 = "{SPELL:205021} pone 8 acumulaciones nuevas de Congelamiento. Un enemigo aguanta como mucho 20, así que gasta primero el Congelamiento viejo.",
	PLAYCARD_64_W5 = "{SPELL:116} añade Congelamiento, y puede hacer que se ilumine {SPELL:190447} o {SPELL:112965}.",
	PLAYCARD_65_HERO2 = "Fragualuz: sin {SPELL:375576}. {SPELL:1289728} empieza como {SPELL:432472}; después de usarlo, el mismo botón se convierte en {SPELL:432459}. Sigue usando las cargas.",
	PLAYCARD_66_HERO2 = "Fragualuz: un solo botón con 2 cargas (puedes pulsarlo dos veces antes de que tenga que recargarse) que alterna Baluarte sagrado y {SPELL:432472}. Púlsalo cuando {SPELL:31884} (o {SPELL:389539}) no esté activo.",
	PLAYCARD_71_HERO1 = "Destripador (el mejor esta temporada): {SPELL:227847} durante {SPELL:167105}. Cada vez que usas {SPELL:163201} iluminado, {SPELL:227847} vuelve antes.",
	PLAYCARD_72_HERO1 = "Destripador: {SPELL:227847} justo después de {SPELL:184367}, durante {SPELL:1719}. Pulsa {SPELL:5308} cada vez que se ilumine.",
	PLAYCARD_72_HERO2 = "Señor feudal montés: {SPELL:6343} en vez de {SPELL:190411}. {SPELL:435222} cada vez que se ilumine; no dejes que se acumulen 2.",
	PLAYCARD_72_S3 = "{SPELL:23881} y {SPELL:85288} generan Ira. Con el talento Abandono temerario, {SPELL:1719} los convierte en versiones más fuertes: sigue pulsándolos.",
	PLAYCARD_73_HERO1 = "Señor feudal montés: {SPELL:6343} a veces se convierte en {SPELL:435222}. Púlsalo enseguida; {SPELL:107574} te da dos.",
	PLAYCARD_DISPEL_SEASON = "Dónde importa en los calabozos y la banda de Midnight",
	PLAYCARD_DISPEL_TIP_FRIENDS = "|cffffd100Tu grupo:|r Opciones > Experiencia de juego > Interfaz > Marcos de banda. Pon \"Indicador de perjuicio disipable\" en \"Solo disipables por el jugador\" y \"Color\" en \"Utilizar color de perjuicio\": así el marco se ilumina con el color del debuff cuando puedes quitarlo. ¿No cambia nada en tus marcos de grupo? Activa \"Usar marcos de grupo estilo banda\" en el Modo de edición.",
	PROFACAD_CH_ENCHANTING_BODY = "Encantamiento es la excepción: ganas la mayoría de tus KP semanales desencantando equipo. Cada semana, las primeras 5 Esencias arcanas turbulentas dan +1 KP cada una, y después un Fragmento de maná rebosante da +4 — eso son +9 KP por semana solo por triturar botín. Además hay dos hallazgos semanales de cofres del tesoro normales (Voidstorm Ashes y Lost Thalassian Vellum, +2 KP cada uno) y, desde habilidad 25, una misión semanal con Dolothos. Los pedidos de la pestaña Cliente no dan conocimiento a Encantamiento.|n|nBuild inicial: primero Disenchanting Delegate — alimenta al resto de la profesión, y es donde empiezan las dos guías mejor mantenidas. Dentro, elige UNO de Dust Deliverer, Shard Supplier o Crystal Collector: ayudan cuando desencantas equipo poco común, raro o épico, así que elige el que encaje con lo que de verdad desmontas. Luego Elevating Equipment — raíz hasta ~30 y después la rama Weapon/Chest/Ring de una familia: la habilidad decide qué rango de calidad alcanzas, y un encantamiento de rango máximo que no puedes hacer es uno que no puedes vender. Spellbound Shatterer al final — sus estadísticas bajan lo que cuesta una fabricación, y eso solo compensa cuando ya puedes hacer la versión buena.|n|nLibros de KP extra: Corte de Lunargenta reconocimiento 6, Zul'jarra's Forces reconocimiento 6 en la Isla Serpenteante (nuevo en 12.1), y el vendedor del evento Abundance (Chel the Chip) también vende un libro de Encantamiento.",
	PROFACAD_CH_GOLD_BODY = "La palabra que la gente se salta es |cfffffffftodo|r. Las hierbas que has recogido tú |cffffffffno son gratis|r. Tienen un precio de mercado, y meterlas en una poción en vez de venderlas significa que lo has gastado — solo que te lo has pagado a ti mismo. Si la hierba vale más que la poción, fabricar es |cffffffffperder dinero de una forma que se siente como ganarlo|r.\n\n|cffffcc00Hay dos mercados, y obedecen a leyes opuestas.|r Casi toda la confusión sobre si una profesión \"renta\" viene de mezclarlos.\n\nEl primero es el de |cffffffffmercancías|r: materiales, pociones, frascos, gemas — todo lo que se apila. Vendes cosas, y compites con toda la región en vez de con tu propio reino. Los compradores no ven más que el precio.\n\nEl segundo es el del |cffffffffequipo fabricado|r. Se queda en tu reino, y lo mejor se vincula a una sola persona, así que ni siquiera puede ir a la casa de subastas. Aquí no vendes cosas, vendes tu artesanía.\n\n|cffffcc00Por qué el mercado de mercancías siempre se hunde|r merece entenderse, y ninguna de las razones es \"hay muchos jugadores\". El juego compra automáticamente la oferta más barata, así que una moneda de cobre por encima del precio más bajo significa no vender. Compites contra todos los reinos de tu región a la vez. La Multifabricación reparte oferta extra gratis, y solo funciona con cosas que se apilan — precisamente este mercado. Y los consumibles tienen solo dos rangos de calidad en lugar de la escalera completa, así que la caída hasta el fondo es más corta.\n\nHay un freno: mientras los fabricantes sigan necesitando Concentración para alcanzar la calidad máxima, la calidad máxima es escasa. En cuanto la alcancen sin ayuda, el freno se suelta y el precio cae. Así que en este mercado ganas en la ventana |cffffffffanterior|r a que eso ocurra.\n\n|cffffcc00Lo que de verdad protege un precio es un candado sobre la oferta.|r Hay cuatro tipos: un cooldown en la receta, un componente que el fabricante nunca puede conseguirse él mismo, una receta detrás de reputación, y la Concentración, porque se rellena despacio. |cffffffffDonde hay candado hay margen. Donde no lo hay, hay volumen y casi ningún margen.|r Ese es todo el tema en una frase.\n\nRecolectar es la excepción que lo demuestra: lo que recoges no tiene coste, así que |cffffffffno puedes|r perder — la única forma de hacer oro en la que un principiante no puede equivocarse. Pero no tener coste significa tampoco tener barrera, así que el precio se asienta en lo que acepte el recolector menos exigente.\n\n|cffffcc00Cada objeto fabricado cae en una de tres cajas, y la tercera es la trampa.|r Lo libremente comerciable lo dice en su propio tooltip: \"Se puede comprar y vender en la casa de subastas.\" Lo que sale \"Ligado\" no se puede subastar pero |cffffffffsí|r se puede vender mediante un pedido, que lo entrega directamente al cliente — ahí vendes trabajo, no producto. Y lo que |cffffffffse liga a la tropa|r no permite ninguna de las dos cosas: ni subasta, ni pedido, solo tú y tus propios alts. Eso no es un negocio, es un servicio.\n\nAlquimistas sobre todo: los dos calderos que abastecen a toda tu banda llevan |cffffffffambos|r \"Se liga a la tropa\". Nunca los vas a poder vender. Los fabricas, los llevas, y lo que recibes a cambio es buena voluntad. Eso está bien — pero debería ser una decisión y no un descubrimiento, porque entran materiales caros.\n\n|cffffcc00¿En volumen o por pedido?|r En volumen vendes el producto, compites en precio con toda la región, tienes volumen ilimitado y un margen que no deja de adelgazar. Por pedido vendes tu artesanía, compites en reputación con los fabricantes de tu propio reino, tienes volumen limitado y un margen más estable. De ahí se sigue una aritmética, no una opinión: |cffffffffla cola de pedidos públicos no es un negocio.|r Guardas cuatro y recuperas uno al día — unos siete a la semana. Eso es calderilla. |cffffffffLos pedidos personales y los de hermandad son ilimitados|r, así que un puñado de clientes fijos que te manden pedidos directamente es donde está el trabajo de verdad.\n\n|cffffcc00El mayor error de principiante|r es fabricar antes de mirar lo que cuestan los materiales. Tiene dos caras y son el mismo error: \"lo he recogido yo, así que es gratis\" y \"tengo esta receta, así que la voy a fabricar\". Tener una receta no dice nada sobre si renta. |cffffffffMira primero lo que cuesta. Y luego decide si lo fabricas.|r\n\nY desconfía de todo \"X de oro por hora\" de una guía o un vídeo: cambia según el reino y suele estar inventado. Mídelo tú en tu propio reino. Auctionator muestra lo que cuestan las cosas de verdad; CraftSim calcula lo que rinde una fabricación frente a los precios de materiales de hoy, y es con diferencia lo más útil que puedes instalar si quieres ganar en serio.",
	PROFACAD_CH_MOXIE_BODY ="El Energizante es una moneda específica de cada profesión: tu Energizante de Encantamiento solo compra cosas de Encantamiento. Ganas más o menos 5x de Energizante por KP, 10x con las primeras fabricaciones, 30x con un pedido de la pestaña Cliente que trae un cofre de Energizante, y 15x con cada uno de los tesoros de profesión únicos de las zonas. Se queda en el personaje que lo ganó: un alter no puede enviarte el suyo.|n|nGástalo en los vendedores de profesiones de Lunargenta en recetas nuevas y bolsas de materiales (alquimistas: Camberon's Cauldron, junto a Camberon). Los libros de +10 puntos de conocimiento también cuestan Energizante, pero los compras a los intendentes de las facciones por las zonas cuando tu reconocimiento es lo bastante alto — los recolectores y Encantamiento también pueden conseguir uno con Chel the Chip, el vendedor de Abundance.|n|nConsejo: no acumules sin fin — las recetas tempranas y los libros de KP son la mejor inversión.",
	PROFACAD_CH_RECIPES_BODY = "Las recetas salen de cinco fuentes: tu instructor (compra mientras subes habilidad), tus árboles de especialización (se desbloquean al gastar PC), los vendedores de Energizante (siguiente capítulo), recompensas de reconocimiento y botín o tesoros del mundo.\n\nRegla de oro: fabrica cada receta nueva al menos una vez. Cada primera fabricación da +1 PC y 10x de Energizante — aunque vendas el resultado al vendedor.\n\n¿Una guía menciona una receta que no tienes? Comprueba primero de dónde sale antes de farmear.",
	PROFACAD_CH_WEEKLY_BODY = "La mayoría de los KP vienen de fuentes semanales repetibles. Lo que puedes conseguir cada semana:|n|n1. Misión semanal — se desbloquea tras la misión introductoria con el Capitán Jurabengala (mesa de pedidos, Bazar de Lunargenta). Los artesanos completan unos cuantos pedidos de fabricación y vuelven a informar a Jurabengala. Encantamiento y las profesiones de recolección llevan materiales a su instructor y necesitan antes habilidad 25. Vale de 1 a 3 KP, según la profesión.|n2. Artesanos, Encantamiento incluido: dos objetos de conocimiento de cofres del tesoro normales en las zonas de Midnight, cada uno una vez por semana — +1 o +2 KP cada uno, según la profesión.|n3. Recolectores, y Encantamiento al desencantar: cinco hallazgos pequeños de +1 KP cada uno, y luego uno más grande (+3, Encantamiento +4). El grande significa que has terminado por esta semana.|n4. Artesanos salvo Encantamiento: pedidos de la pestaña Cliente en tu propio banco de trabajo — la mayor fuente semanal de todas, con su propio capítulo más abajo.|n5. Un Tratado thalassiano (+1 KP, usable desde habilidad 25) — lo fabrica Inscripción; ligado a la tropa, así que un alter o un pedido te consigue uno.|n6. Semana de la Feria de la Luna Negra: +3 KP, cada mes (no está claro si también da Energizante: las guías no se ponen de acuerdo).|n|n¿Te saltaste una semana? El sistema de recuperación devuelve poco a poco los KP perdidos — después de terminar las semanales actuales.",
	PROFACAD_CH_WORKORDERS_BODY = "Funciona así porque el mejor equipo fabricado se vincula a una sola persona en el momento en que existe. Nadie puede hacerlo por adelantado y ponerlo en el estante, así que alguien tiene que fabricarlo |cffffffffespecialmente para ti|r.\n\n|cffffcc00Hay dos mostradores, y aquí es donde suele torcerse.|r Para que te fabriquen algo, ve a la mesa de pedidos del Bazar de Lunargenta — el gran martillo dorado de tu minimapa. La persona que necesitas es Mar'nah. Para fabricar algo para otra persona, ve en cambio al |cffffffffbanco de trabajo de tu propia profesión|r. Si no estás justo al lado no hay botón ni lista, y parece que el sistema no existiera. Ese es el error más habitual, y el juego no lo explica en ninguna parte.\n\n|cffffcc00Que te fabriquen algo.|r Elige tu objeto y elige después a quién se lo pides. A nadie en particular (un pedido de fabricación público): todo tu reino lo ve y lo fabrica el primero que lo acepte. Rápido, pero te llevas lo que salga — |cffffffffaquí no puedes exigir una calidad|r, y tienes que enviar tú todos los materiales. A un jugador concreto (un pedido de fabricación personal): aquí sí puedes fijar una calidad mínima, y pueden acordar que ponga materiales suyos. A toda tu hermandad (un pedido de fabricación de hermandad) funciona igual y llega a compañeros de hermandad de otros reinos. Tú fijas el pago, y un botón al lado muestra lo que han pagado otros hace poco por el mismo objeto.\n\nTres cosas que saber antes de pulsar el botón de pedir. Algunos componentes especiales no los puede aportar nunca el fabricante, así que esos los envías siempre tú. Los materiales de tu banco de tropa |cffffffffno cuentan|r — ponlos en tus bolsas. Y el objeto se vincula a |cffffffffti|r, así que haz el pedido con el personaje que lo va a llevar, no con el que guarda el oro. Una vez que alguien acepta el pedido ya no lo puedes cancelar; el objeto llega por correo.\n\n|cffffcc00Fabricar para otros.|r En tu banco de trabajo ves lo que vas a ganar antes de empezar. En cuanto empiezas tienes |cffffffff30 minutos|r para terminar — suficiente para ir a por algo, no para irte a comer.\n\nNo puedes aceptar pedidos públicos sin parar: guardas |cffffffffcuatro|r, y |cffffffffvuelve uno cada día|r. Así que unos siete a la semana, no cuatro al día. Los pedidos casi caducados se pueden aceptar gratis.\n\nSi un pedido te rechaza es por una de cuatro cosas: no conoces la receta, tu especialización no llega para los extras que pide, quiere una calidad que no alcanzas, o has agotado tu cupo.\n\nY uno que te cuesta dinero en silencio: |cffffffffmira de quién son los materiales que estás usando.|r En los pedidos públicos el cliente aporta siempre todo, pero en los otros tipos puede no aportar nada — y entonces estás fabricando alegremente con tus propias existencias caras a cambio de una propina.",
	PROFGUIDE_LVL_BLACKSMITHING ="|cffffcc00Subir habilidad 1-100 (rápido y barato)|r|n• Instructor: Bemarrin en la Ciudad de Lunargenta; el vendedor de suministros junto a él vende Luminant Flux, Blacksmith Hammer y las recetas de equipo épico (para Energizante de artesano herrero). Combina mejor con Mining para recolectar tu propio mineral.|n|n|cffffcc00Lista de compra 1-50|r: 125 Refulgent Copper Ore, 100 Refulgent Copper Ingot (o 500 mineral extra para fundirlo tú mismo), 6 Brilliant Silver Ore, 6 Umbral Tin Ore, 1 Duskshrouded Stone. Para 50-70: 300 Brilliant Silver Ore más 150 lingotes más.|n|n|cffffcc00La ruta|r|n• 1-15: funde 25x Refulgent Copper Ingot.|n• 15-50: marca el filtro \"First Craft Bonus\", fabrica una vez cada receta, aprende nuevas recetas del instructor y repite hasta las 28; equipa el Thalassian Blacksmith's Toolbox y Hammer.|n• 50-70: fabrica 50x Sterling Alloy.|n• 70-100: apresura con equipo de profesión raro mediante la spec Craftsmithing (1 de habilidad cada uno, sin mats limitados por tiempo), o usa equipo épico / crafting orders (3 de habilidad cada uno, ~10 para terminar).|n|n|cffffcc00Consejo|r: tu primera especialización se desbloquea en habilidad 25. Las herramientas raras Sun-Blessed (Pickaxe, Hammer, Skinning Knife) son BoE, así que puedes vender las que fabriques mientras subes.",
	PROFGUIDE_LVL_TAILORING = "|cffffcc00Subir habilidad 1-100 (rápido y barato)|r|n• Instructor: Galana en la Ciudad de Lunargenta; el vendedor de suministros junto a ella vende Silverleaf Thread, Embroidery Floss y las recetas Elegant Artisan (para Energizante de artesano sastre).|n|n|cffffcc00Lista de compra 1-50|r: 66 Bright Linen, 14 Eversinging Dust.|n|n|cffffcc00La ruta|r|n• 1-25: fabrica 66x Bright Linen Bolt - guárdalos todos, los necesitas para recetas posteriores incluso después de que se vuelvan grises.|n• 25-40: fabrica 14x Imbued Bright Linen Bolt.|n• 40-45: marca el filtro \"First Craft Bonus\" y fabrica una vez cada receta restante; equipa la Bright Linen Tailoring Robe.|n• 44-50: fabrica 6x Courtly Shoulders.|n• 50-100: mejor hacerlo despacio - gasta 5 puntos en Nimble Needlework para desbloquear un CD diario de bolt (Sunfire Silk Bolt o Arcanoweave Bolt) y sube con eso. Para apresurar: Bright Linen Spellthread (50-65), Sunfire Silk/Arcanoweave Lining (65-90), luego objetos Elegant Artisan como el Cooking Hat (90-100).|n|n|cffffcc00Consejo|r: tu primera especialización se desbloquea en habilidad 25. Tailoring es lento para alcanzar la calidad Gold garantizada, así que hay poca razón para apresurarse - la vía del CD diario también hace oro.",
	PROFGUIDE_SEC_101_BODY = "|cffffcc00Día 1 — haz esto hoy|r|n|n1. Pulsa |cffffff00K|r (Profesiones) y asegúrate de que tus dos profesiones están aprendidas. ¿Aún no? |cffffff00Pestaña SMC|r en este addon → punto de ruta al instructor.|n2. Fabrica cada |cffffff00receta nueva que brilla|r una vez por profesión (las más baratas primero).|n3. En Lunargenta: |cffffff00mesa de pedidos|r → pedidos de clientes que dan |cffffff00conocimiento|r.|n4. |cffffff00Pestaña Profesiones|r aquí → marcas en el mapa para tesoros y libros que aún te faltan.|n5. Encanta tu |cffffff00arma y anillos|r.|n6. Abajo, elige |cffffff00Sastrería + Encantamiento|r si esa es tu combinación (plan para ti, tus amigos y oro).|n|n|cffffcc00¿Qué es una profesión?|r|nUna profesión es un oficio de tu personaje. Algunas profesiones |cffffff00fabrican|r objetos (artesanía). Otras |cffffff00recolectan|r materiales en el mundo (hierbas, mineral, pieles).|n|n|cffffcc00¿Cuántas puedo aprender?|r|n|n• Cada personaje puede aprender |cffffff002 profesiones principales|r en total: de fabricación, de recolección o una de cada (ejemplo: Alquimia + Herboristería, o Sastrería + Encantamiento).|n• |cffffff00Cocina|r y |cffffff00Pesca|r son extra — cualquiera puede aprenderlas además, como aficiones.|n• Muchos jugadores usan |cffffff00otros alters|r de su tropa: un alter recolecta, otro fabrica, y mandas los materiales por el banco.|n|n|cffffcc00Puntos de conocimiento (KP)|r|nLos KP son puntos para tus |cffffff00árboles de especialización|r (como talentos extra para esa profesión). Más KP = mejores recetas y mayor calidad de objeto.|n|n|cffffcc00Energizante|r|nEl Energizante es una moneda |cffffff00por profesión|r en ese personaje. El Energizante de Alquimia solo compra cosas de Alquimia — no se pasa a Encantamiento. Ganas algo de Energizante cuando ganas KP.|n|n|cffffcc00Bonificación de primera fabricación|r|nFabrica cada receta |cffffff00nueva|r una vez si te lo puedes permitir. Las recetas nuevas suelen brillar en tu lista. Cada primera fabricación suele dar +1 KP (y Energizante). Empieza por las recetas baratas.|n|n|cffffcc00Tu rutina semanal|r (haz esto cada semana)|n|n1. Haz tu |cffffff00misión semanal de profesión|r. Artesanos: la primera vez, haz la breve introducción con el |cffffff00Capitán Jurabengala|r (mesa de pedidos); después la semanal pide unos cuantos pedidos de fabricación y se la entregas a él. Recolectores y Encantamiento (desde habilidad 25): tu instructor pide materiales.|n2. Abre la |cffffff00mesa de pedidos|r en Lunargenta.|n3. Haz |cffffff00pedidos de clientes|r que dan |cffffff00Glimmer of … Knowledge|r (+2 KP) o |cffffff00Flicker|r (+1 KP, recuperación).|n4. Usa la pestaña |cffffff00Profesiones|r de este addon para encontrar |cffffff00tesoros|r y |cffffff00libros|r únicos en el mapa.|n5. Opcional: la misión de profesión de la Feria de la Luna Negra (+3 KP, una vez al mes) y un |cffffff00Tratado thalassiano|r por semana (+1 KP). Los tratados están ligados a la tropa, así que no están en la Casa de Subastas: fabrícalos en un alter con Inscripción o haz un pedido de fabricación.|n6. Simplemente juega tu profesión: los artesanos encuentran 2 objetos de conocimiento por semana en tesoros del mundo; los recolectores y los encantadores reciben cada semana 5 objetos pequeños de conocimiento y luego 1 más grande al recolectar o desencantar. Haz clic derecho en ellos para aprender el conocimiento.|n|n|cffffcc00Pedidos de fabricación — cuatro tipos|r|n|n|cffffff00Cliente|r — Encargos de PNJ en el tablón. Lo mejor para aprender y para KP constantes.|n|cffffff00Público|r — Otros jugadores te pagan por fabricarles cosas. Bueno para oro cuando ya conoces una receta.|n|cffffff00Hermandad|r — Pedidos de tus compañeros de hermandad.|n|cffffff00Personal|r — Un jugador te envía un pedido a tu nombre.|n|n|cffffcc00Especializaciones|r|nLos árboles se desbloquean hacia habilidad |cffffff0025, 50, 60 y 75|r. No repartas los puntos por todas partes a la vez. Elige un objetivo: |cffffff00frascos para bandas|r, |cffffff00encantamientos para vender|r, |cffffff00equipo de cuero|r, etc.|n|n|cffffcc00Oro en la Casa de Subastas|r|n|n• Céntrate en |cffffff001–2 productos|r que puedas fabricar de forma fiable — no veinte objetos distintos.|n• Mira la Casa de Subastas |cffffff00antes|r de fabricar un montón: precio de los materiales frente al objeto terminado.|n• Frascos de banda, encantamientos de arma y de anillo son ventas clásicas — pero los precios cambian cada semana.|n• Rebajar 1 de cobre es normal; no fabriques 200 objetos si nadie compra.|n|n|cffffcc00Usa este addon|r|n|n• |cffffff00Pestaña Profesiones|r = KP en directo, monedas semanales, marcas de tesoros/libros.|n• |cffffff00Pestaña SMC|r = instructores en Lunargenta.|n• Secciones de abajo = planes sencillos por profesión.",
	PROFGUIDE_SEC_ALCHEMY_BODY = "|cffffcc00Qué hace|r|nConvierte hierbas en |cffffff00pociones|r (buffs cortos) y |cffffff00frascos|r (buffs largos para bandas). Genial para |cffffff00ti mismo|r y para |cffffff00oro|r.|n|n|cffffcc00Buena combo|r|nAprende |cffffff00Herbalism|r en este personaje o en un alt-recolector y envía las hierbas por el banco de tropa.|n|n|cffffcc00Lista semana 1|r|n|n• Aprende Alchemy en Lunargenta.|n• Fabrica cada |cffffff00receta nueva|r barata una vez (KP de primera fabricación).|n• Termina la |cffffff00misión semanal del instructor|r (normalmente 3 orders).|n• Haz Pedidos de clientes con |cffffff00Glimmer of Alchemy Knowledge|r.|n• Elige un camino: |cffffff00frascos|r O |cffffff00pociones|r — no ambos al principio.|n|n|cffffcc00Dónde gastar KP — para ti|r|n|n• Pon los primeros puntos en la especialización que desbloquea |cffffff00los frascos que usa tu banda|r.|n• Pregunta a tu hermandad o mira la CdS: ¿qué frasco se vende más este nivel?|n• La calidad importa: frasco de mayor calidad = buff más fuerte. Usa |cffffff00Concentration|r en los crafts importantes (el juego lo muestra en la pantalla de fabricación).|n|n|cffffcc00Dónde gastar KP — para oro|r|n|n• Misma idea: un |cffffff00frasco de banda popular|r por temporada.|n• Vigila el coste de materiales vs el precio del frasco una semana antes de comprometerte.|n• No fabriques 50 frascos si la CdS ya está inundada.|n|n|cffffcc00Crafting orders|r|nLos Pedidos de clientes son tu mejor amigo. Las Public Orders pueden pagar bien una vez tu habilidad alcanza |cffffff00Quality 2–3|r.|n|n|cffffcc00Casa de Subastas|r|nVende los |cffffff00frascos|r antes de las noches de banda (martes/miércoles en muchos reinos). Las pociones también se venden, a menudo en cantidades menores.",
	PROFGUIDE_SEC_ENCHANTING_BODY ="|cffffcc00Qué hace|r|nPone |cffffff00encantamientos|r en armas y armadura. También |cffffff00desencantas|r equipo viejo en polvo y esquirlas.|n|n|cffffcc00Lista semana 1|r|n|n• Aprende Enchanting en Lunargenta.|n• Desencanta equipo |cffffff00verde y azul|r que no necesites (KP constantes mientras subes de nivel).|n• Primera fabricación de cada fórmula barata una vez.|n• Misión semanal + Patron Orders con recompensas conocimiento.|n|n|cffffcc00Dónde gastar KP — para ti|r|n|n• Pronto: puntos que ayudan a |cffffff00desencantar|r y fabricar materiales básicos.|n• Luego: encantamientos para |cffffff00tus propios slots de equipo|r (arma primero, luego anillo/muñequeras).|n|n|cffffcc00Para amigos y hermandad|r|n|n• Ofrece encantamientos de arma y anillo antes de calabozos o banda.|n• Te dan el objeto, o encantas sobre pergamino que compraron.|n• Apunta 2–3 \"encantamientos de la casa\" que siempre tengas listos.|n• Con Tailoring en el mismo personaje: tú cubres encantamientos, ellos traen la tela si fabricas para ellos.|n|n|cffffcc00Dónde gastar KP — para oro|r|n|n• Los |cffffff00encantamientos de anillo|r y |cffffff00de arma|r siempre tienen demanda.|n• Elige |cffffff00un|r mercado (armas O anillos) para no quedarte sin KP.|n• Publica los encantamientos como objetos en la CdS — los jugadores compran el pergamino/encantamiento y lo aplican ellos mismos.|n|n|cffffcc00Crafting orders|r|nLas Public Orders para encantamientos populares pueden ser buen oro. Las Patron Orders siguen importando para los KP cada semana.|n|n|cffffcc00Consejo|r|nGuarda una bolsa de verdes inútiles de misiones de mundo y abismos — desencántalos en vez de venderlos.",
	PROFGUIDE_SEC_HERBALISM_BODY = "|cffffcc00Qué hace|r|n|cffffff00Recoges hierbas|r en el mundo. Las hierbas alimentan la |cffffff00Alchemy|r y algunas otras profesiones.|n|n|cffffcc00¿Quién debería aprenderla?|r|n|n• Cualquiera que quiera |cffffff00ahorrar oro|r en pociones/frascos.|n• A menudo en un |cffffff00segundo personaje|r mientras tu main hace Alchemy.|n|n|cffffcc00Lista semana 1|r|n|n• Aprende Herboristería — no necesita crafting orders para el ciclo semanal como los fabricantes.|n• Recolecta mientras haces misiones de mundo y abismos.|n• Recoge los |cffffff00tesoros|r de mapa (la pestaña Profesiones del addon muestra las marcas).|n• Gasta KP en nodos que dan |cffffff00más hierbas por nodo|r o |cffffff00recolección más rápida|r.|n|n|cffffcc00Dónde gastar KP|r|n|n• Elige una zona o tipo de hierba que más farmees.|n• Los nodos de agotamiento y velocidad son fuertes para principiantes.|n|n|cffffcc00Oro|r|nVende las hierbas en bruto en la CdS cuando los precios estén altos (a menudo la semana de salida de una banda). Incluso sin Alchemy, solo las hierbas pueden dar oro.|n|n|cffffcc00Funciona con|r|nEnvía las hierbas a tu alquimista por el |cffffff00banco de tropa|r.",
	PROFGUIDE_SEC_SKINNING_BODY = "|cffffcc00Qué hace|r|n|cffffff00Despellejas bestias|r por cuero. El cuero alimenta el |cffffff00Leatherworking|r.|n|n|cffffcc00¿Quién debería aprenderla?|r|n|n• Combina con |cffffff00Leatherworking|r (mismo personaje o alt).|n• Genial mientras subes de nivel — mata mobs, despelléjalos.|n|n|cffffcc00Lista semana 1|r|n|n• Aprende Skinning.|n• Despelleja cada bestia que mates en abismos y mundo abierto.|n• Tesoros de mapa vía la pestaña Profesiones.|n• KP: más cuero por despellejado y recolección más rápida.|n|n|cffffcc00Oro|r|nVende lotes de cuero en la CdS, o fabrica con Leatherworking para más beneficio.|n|n|cffffcc00Consejo|r|nNo necesitas una estación de fabricación para despellejar — solo un cuchillo de despellejar en las bolsas.",
